script:
(function () {
  'use strict';
  // Debt consolidation: current debts (each paid at its own fixed monthly payment until cleared)
  // vs one new fixed-rate installment loan.
  //   Current debts: interest = balance x APR / 12 each month (rounded to the cent), then the payment.
  //   New loan: amount L = total debts D, plus the fee when it is financed. A percentage fee that is
  //   financed is charged on the whole loan, so L = D / (1 - f) and the fee is L - D. Payment
  //   P = rL / (1 - (1 + r)^-n) rounded to the cent (L / n at 0%); the last of the n payments is adjusted to clear the balance.
  //   APR with fees: the monthly rate i solving P x (1 - (1 + i)^-n) / i = L - fee (the cash you
  //   actually receive), found by bisection, x 12.
  // Verified (scratchpad w2debt/dc.test.js):
  //   $20,000 at 10% for 5 years -> $424.94 a month (standard amortization table value), 60
  //   payments, $5,496.45 interest (the last payment absorbs the 5 cents of rounding);
  //   APR with fees: $10,000 at 10% for 36 months with a $500 fee -> payment $322.67 and APR 13.56%,
  //   checked by discounting the 36 payments at that rate back to $9,500 (to the cent); with no
  //   fee the same routine returns 10.00%;
  //   a 4% fee financed on $18,000 -> loan $18,750, fee $750 (= 4% of the loan);
  //   0% loan produces no interest; a debt whose payment is at or below its interest is reported
  //   by name instead of producing a result;
  //   default example: current debts $18,000, $565 a month, 64 months, $11,397.40 interest;
  //   consolidation loan $18,750 at 12% for 5 years: $417.08 a month, $6,275.08 interest,
  //   APR with the fee 13.81%, total cost $25,025.08 vs $29,397.40.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card 1', balance: 8000, apr: 23.99, pay: 240 },
    { name: 'Credit card 2', balance: 5500, apr: 27.49, pay: 165 },
    { name: 'Personal loan', balance: 4500, apr: 15, pay: 160 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var rowCounter = 0;

  function cents(x) { return Math.round(x * 100) / 100; }

  // Pays a fixed amount every month until the balance is gone.
  function payDown(balance, apr, payment) {
    var r = apr / 12, bal = balance, interestTotal = 0, paid = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = Math.min(payment, bal);
      bal -= pay; interestTotal += interest; paid += pay;
      if (bal <= 0.005) return { paidOff: true, months: m, interest: interestTotal, paid: paid };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interestTotal, paid: paid };
  }

  // A fixed-rate installment loan: n payments of P, the last one adjusted to clear the balance.
  function amortize(amount, apr, months, payment) {
    var r = apr / 12, bal = amount, interestTotal = 0, paid = 0, m;
    for (m = 1; m <= months; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = m === months ? bal : Math.min(payment, bal);
      bal -= pay; interestTotal += interest; paid += pay;
      if (bal <= 0.005) break;
    }
    return { months: Math.min(m, months), interest: interestTotal, paid: paid };
  }

  function levelPayment(amount, apr, months) {
    var r = apr / 12;
    var p = r === 0 ? amount / months : r * amount / (1 - Math.pow(1 + r, -months));
    return cents(p);
  }

  // Loan amount and fee given the debts to pay off and how the fee is handled.
  function loanAmount(debt, feeValue, feeUnit, financed) {
    var fee;
    if (feeUnit === 'percent') {
      var f = feeValue / 100;
      if (financed) { var L = debt / (1 - f); return { loan: L, fee: L - debt }; }
      fee = debt * f;
    } else {
      fee = feeValue;
      if (financed) return { loan: debt + fee, fee: fee };
    }
    return { loan: debt, fee: fee };
  }

  function pv(payment, i, n) { return i === 0 ? payment * n : payment * (1 - Math.pow(1 + i, -n)) / i; }

  // Annual rate (decimal) at which n payments of P are worth `received` today.
  function aprWithFees(payment, n, received) {
    if (received <= 0 || payment * n <= received) return 0;
    var lo = 0, hi = 1;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pv(payment, mid, n) > received) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2 * 12;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function pct(x) { return (x * 100).toFixed(2) + '%'; }

  function signedMoney(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  // ---- Debt rows (DOM methods only; user text is set as values or textContent) ----
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('dcDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex items-center justify-between gap-3');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows();
      update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'dcName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'dcName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('dcBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('dcApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('dcPay' + n, 'Monthly payment', d.pay, '$', true, '5'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('dcDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var btn = row.querySelector('[data-remove]');
      btn.disabled = rows.length <= 1;
      btn.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('dcAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('dcDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('dcName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('dcBal' + n), aprEl = document.getElementById('dcApr' + n), payEl = document.getElementById('dcPay' + n);
      var bal = parseFloat(balEl.value), apr = parseFloat(aprEl.value), pay = parseFloat(payEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, payEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badPay = isNaN(pay) || pay <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      payEl.setAttribute('aria-invalid', String(badPay));
      if (badBal || badApr || badPay) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, pay: pay });
    });
    return { ok: ok, debts: out };
  }

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function clearResults() {
    ['dcNewPay', 'dcPayChange', 'dcSavings', 'dcApr'].forEach(function (id) { set(id, '–'); });
    ['dcPayNote', 'dcPayNote2', 'dcSavingsNote', 'dcAprNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('dcVerdict').hidden = true;
    clearBody('dcCompare'); clearBody('dcDebtTable');
  }

  function update() {
    var error = document.getElementById('dcError');
    var rate = num('dcRate'), years = num('dcYears'), feeValue = num('dcFee');
    var feeUnit = document.getElementById('dcFeeUnit').value, financed = document.getElementById('dcFinanceFee').checked;
    if (isNaN(feeValue)) feeValue = 0;
    var months = Math.round(years * 12);
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) problem = 'Enter a new loan rate from 0 to 100%.';
    else if (isNaN(years) || years < 1 || years > 30) problem = 'Enter a new loan term from 1 to 30 years.';
    else if (feeValue < 0 || (feeUnit === 'percent' && feeValue >= 50)) problem = 'Enter a fee of $0 or more (below 50% when entered as a percentage).';
    var current = [];
    if (!problem) {
      input.debts.some(function (d) {
        var s = payDown(d.balance, d.apr, d.pay);
        if (!s.paidOff) { problem = 'The payment on “' + d.name + '” does not cover its monthly interest of about ' + money.format(d.balance * d.apr / 12) + ', so it never gets paid off. Raise that payment.'; return true; }
        current.push(s);
        return false;
      });
    }
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var debts = input.debts;
    var D = debts.reduce(function (s, d) { return s + d.balance; }, 0);
    var curPay = debts.reduce(function (s, d) { return s + d.pay; }, 0);
    var curMonths = Math.max.apply(null, current.map(function (s) { return s.months; }));
    var curInterest = current.reduce(function (s, x) { return s + x.interest; }, 0);
    var curCost = D + curInterest;
    var weighted = debts.reduce(function (s, d) { return s + d.balance * d.apr; }, 0) / D;

    var la = loanAmount(D, feeValue, feeUnit, financed);
    var payment = levelPayment(la.loan, rate / 100, months);
    var loan = amortize(la.loan, rate / 100, months, payment);
    var upfront = financed ? 0 : la.fee;
    var newCost = loan.paid + upfront;
    var apr = aprWithFees(payment, months, la.loan - la.fee);

    set('dcNewPay', money.format(payment));
    set('dcPayNote', 'Loan amount ' + money.format(la.loan) + ' over ' + duration(months) + '.');
    var change = payment - curPay;
    set('dcPayChange', signedMoney(change));
    set('dcPayNote2', change < 0 ? 'Less each month than the ' + money.format(curPay) + ' you pay now.' : 'More each month than the ' + money.format(curPay) + ' you pay now.');
    var saving = curCost - newCost;
    set('dcSavings', money.format(Math.abs(saving)));
    set('dcSavingsLabel', saving >= 0 ? 'Total saved' : 'Extra total cost');
    set('dcSavingsNote', 'Interest and fees, over the life of each option.');
    set('dcApr', pct(apr));
    set('dcAprNote', 'Your debts average ' + pct(weighted) + ' (balance-weighted).');

    var verdict = document.getElementById('dcVerdict');
    verdict.hidden = false;
    verdict.className = 'callout mt-5 ' + (saving >= 0 ? 'callout-success' : 'callout-warning');
    set('dcVerdictTitle', saving >= 0 ? 'The loan costs less overall' : 'The loan costs more overall');
    set('dcVerdictText', saving >= 0
      ? 'Consolidating saves ' + money.format(saving) + ' in total and you are debt-free ' + (loan.months <= curMonths ? duration(curMonths - loan.months) + ' sooner' : duration(loan.months - curMonths) + ' later') + ', as long as the paid-off accounts are not used again.'
      : 'Even though ' + (change < 0 ? 'the monthly payment is lower' : 'you get a single payment') + ', the loan costs ' + money.format(-saving) + ' more in interest and fees' + (loan.months > curMonths ? ', mainly because it stretches repayment ' + duration(loan.months - curMonths) + ' longer.' : '.'));

    var cmp = clearBody('dcCompare');
    addRow(cmp, ['Monthly payment', money.format(curPay), money.format(payment), signedMoney(payment - curPay)]);
    addRow(cmp, ['Time to debt-free', duration(curMonths), duration(loan.months), (loan.months === curMonths ? 'Same' : (loan.months < curMonths ? duration(curMonths - loan.months) + ' sooner' : duration(loan.months - curMonths) + ' later'))]);
    addRow(cmp, ['Total interest', money.format(curInterest), money.format(loan.interest), signedMoney(loan.interest - curInterest)]);
    addRow(cmp, ['Fees', money.format(0), money.format(la.fee), signedMoney(la.fee)]);
    addRow(cmp, ['Total cost (debt + interest + fees)', money.format(curCost), money.format(newCost), signedMoney(newCost - curCost)]);

    var tb = clearBody('dcDebtTable');
    debts.forEach(function (d, i) {
      addRow(tb, [d.name, money.format(d.balance), pct(d.apr), money.format(d.pay), duration(current[i].months), money.format(current[i].interest)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('dcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('dcAdd').addEventListener('click', function () {
      if (document.getElementById('dcDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', pay: '' });
      update();
    });
    update();
  });
})();
